/** Relative monthly volume: early peak, plateau, slight recent decline. */
function monthWeight(index: number): number {
  const early = [0.5, 3.2, 2.6, 2.0, 1.6][index]
  if (early) return early
  return 1.05 + 0.18 * Math.sin(index / 3.2) - index * 0.006
}

function verificationFor(monthsAgo: number): Verification {
  const maturity = Math.min(1, monthsAgo / 18) // older records have had time to be verified
  return pick<Verification>([
    ['verified', 10 + 26 * maturity],
    ['corroborated', 20 + 14 * maturity],
    ['reported', 42 - 16 * maturity],
    ['unverified', 28 - 22 * maturity],
  ])
}

function statusFor(v: Verification): RecordStatus {
  if (v === 'unverified') return 'under-review'
  if (v === 'verified')
    return pick<RecordStatus>([
      ['documented', 6],
      ['referred', 4],
    ])
  return pick<RecordStatus>([
    ['documented', 8],
    ['under-review', 2],
    ['referred', 1],
  ])
}

const TARGET_TOTAL = 12_847

function generate(): Incident[] {
  const end = todayISO()
  const [endY, endM] = end.split('-').map(Number)
  const months: { y: number; m: number }[] = []
  for (let y = 2022, m = 2; y < endY || (y === endY && m <= endM); m === 12 ? ((m = 1), y++) : m++) months.push({ y, m })
  const weights = months.map((_, i) => monthWeight(i))
  const weightSum = weights.reduce((a, b) => a + b, 0)
  const generatedTotal = TARGET_TOTAL - TEMPLATE_RECORDS.length

  const out: Omit<Incident, 'id'>[] = [...TEMPLATE_RECORDS]
  let assigned = 0
  months.forEach(({ y, m }, i) => {
    const isLast = i === months.length - 1
    const count = isLast ? generatedTotal - assigned : Math.round((weights[i] / weightSum) * generatedTotal)
    assigned += count
    const firstDay = i === 0 ? 24 : 1
    const lastDay = isLast ? Number(end.slice(8, 10)) : new Date(Date.UTC(y, m, 0)).getUTCDate()
    for (let k = 0; k < count; k++) {
      const day = firstDay + Math.floor(rand() * (lastDay - firstDay + 1))
      const victimGroup = pick(GROUP_WEIGHTS)
      const knownAge = rand() < 0.62 // age information exists only for a subset
      const ageGroup: AgeGroup | null = !knownAge
        ? null
        : victimGroup === 'under-18'
          ? 'under-18'
          : victimGroup === 'older'
            ? '55+'
            : pick(ADULT_AGES)
      const verification = verificationFor(months.length - 1 - i)
      out.push({
        date: `${y}-${String(m).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
        region: pick(REGION_WEIGHTS),
        type: pick(TYPE_WEIGHTS),
        victimGroup,
        ageGroup,
        source: pick(SOURCE_WEIGHTS),
        verification,
        status: statusFor(verification),
      })
    }
  })

  return out
    .sort((a, b) => a.date.localeCompare(b.date))
    .map((r, i) => ({ ...r, id: `UA-${String(i + 1).padStart(5, '0')}` }))
    .reverse()
}

/** DEMO DATA — synthetic records, newest first. */
export const DEMO_INCIDENTS: Incident[] = generate()
